        $testRule.Stop | Should -BeFalse
    }

    It 'reads the Stop flag when present' {
        $rules = Import-PrLabelRule -Path $script:ConfigPath
        $depRule = $rules | Where-Object { $_.Pattern -eq 'package.json' }
        $depRule.Stop | Should -BeTrue
    }

